transcript.content:
DIRECTIVE:
{
  "scope_id": "critical_path-3-r3",
  "supersedes": "critical_path-2-r2",
  "version": 2,
  "objective": "Complete platform by finishing branch",
  "priorities": [
    "Finish branch",
    "Stay within budget"
  ],
  "constraints": [
    "spec must work on branch",
    "gen must idle",
    "Total spend must not exceed 40"
  ],
  "responsibilities": [
    {
      "owner": "spec",
      "responsibility": "branch"
    },
    {
      "owner": "gen",
      "responsibility": "-"
    }
  ],
  "success_conditions": "branch completed",
  "review_when": "end of episode",
  "decision_summary": "Reallocated spec to branch to complete platform; gen idles as all light work is done."
}

DIRECTIVE: {
  "scope_id": "allocation-1-r3",
  "supersedes": "allocation-1-r2",
  "version": 2,
  "objective": "Complete polish objective by finishing trim workstream within remaining budget.",
  "priorities": [
    "Finish trim workstream",
    "Maintain total spend <= 48"
  ],
  "constraints": [
    "Total spend must not exceed 48",
    "spec must idle due to high cost relative to remaining budget",
    "gen must work on trim to meet effort requirement within budget"
  ],
  "responsibilities": [
    {
      "owner": "spec",
      "responsibility": "-"
    },
    {
      "owner": "gen",
      "responsibility": "trim"
    }
  ],
  "success_conditions": "trim workstream completed, total episode spend <= 48",
  "review_when": "end_of_episode",
  "decision_summary": "Remaining budget (6) restricts actor allocation. spec cost (5/tick) prevents viable trim completion. gen assigned to trim (cost 1/tick, rate 2) to deliver 8 effort over 4 ticks within budget. spec idles."
}

DIRECTIVE: {
  "scope_id": "allocation-6-final",
  "supersedes": "allocation-6-default",
  "version": 1,
  "objective": "Complete assembly objective by finishing fit workstream within remaining budget",
  "priorities": [
    "assembly",
    "secure",
    "polish"
  ],
  "constraints": [
    "Total spend must not exceed 48",
    "Actors may only work on compatible workstreams",
    "No actor may be assigned twice"
  ],
  "responsibilities": [
    {
      "owner": "spec",
      "responsibility": "-"
    },
    {
      "owner": "gen",
      "responsibility": "fit"
    }
  ],
  "success_conditions": [
    "fit workstream completed",
    "total episode spend <= 48",
    "assembly objective delivered"
  ],
  "review_when": "end of episode",
  "decision_summary": "Reallocate gen to fit to capture assembly value within remaining budget; idle spec to avoid breach; accept polish shortfall."
}

DIRECTIVE:
{
  "scope_id": "disruption-8-default",
  "supersedes": "disruption-8-default",
  "version": 1,
  "objective": "Secure Product (27) and Side (14) objectives by completing Widget, Polish, and Gadget within remaining budget and time.",
  "priorities": [
    "Complete Widget to unblock Polish and secure Product objective.",
    "Complete Polish to finish Product objective.",
    "Complete Gadget to finish Side objective."
  ],
  "constraints": [
    "Total episode spend must not exceed 45.",
    "Actors must only work on compatible workstreams.",
    "Polish cannot start until Widget is complete."
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "widget"
    },
    {
      "owner": "bo",
      "responsibility": "widget"
    }
  ],
  "success_conditions": [
    "Widget, Polish, and Gadget are complete by tick 12.",
    "Total spend remains under 45."
  ],
  "review_when": "next review",
  "decision_summary": "Reassigned Ana from completed Pipeline to Widget to accelerate the critical path for the high-value Product objective. Bo continues on Widget. This parallel effort clears the blocker for Polish and ensures all objectives are met within budget."
}

DIRECTIVE: {
  "scope_id": "disruption-10-plan",
  "supersedes": "disruption-10-plan",
  "version": 2,
  "objective": "Pursue product and side objectives by completing widget, gadget, and polish within the remaining budget and deadline.",
  "priorities": [
    "Clear widget to unblock polish",
    "Complete gadget to resolve repeated stagnation",
    "Complete polish"
  ],
  "constraints": [
    "Total episode spend must not exceed 45",
    "Polish blocked until widget completes",
    "Actors limited to their declared skills"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "widget"
    },
    {
      "owner": "bo",
      "responsibility": "gadget"
    }
  ],
  "success_conditions": [
    "Widget, gadget, and polish completed by tick 12",
    "Total spend remains at or below 45"
  ],
  "review_when": "Next review or when widget completes",
  "decision_summary": "Reallocated ana to widget and bo to gadget to simultaneously clear the polish blocker and address gadget stagnation, keeping all remaining objectives viable within the tight budget."
}

DIRECTIVE: {
  "scope_id": "disruption-10-plan",
  "supersedes": "disruption-10-plan",
  "version": 2,
  "objective": "Deliver the product objective (widget + polish) within remaining budget and ticks.",
  "priorities": [
    "Complete widget to unblock polish",
    "Complete polish",
    "Abandon gadget"
  ],
  "constraints": [
    "Total spend must not exceed 45",
    "Polish blocked until widget completes",
    "Bo is unavailable",
    "Only 4 ticks remain"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "widget"
    },
    {
      "owner": "bo",
      "responsibility": "-"
    }
  ],
  "success_conditions": [
    "Widget and polish completed by tick 12",
    "Total spend <= 45"
  ],
  "review_when": "end of episode",
  "decision_summary": "Bo is unavailable and only 12 effort remains. Ana is reallocated to widget to unblock polish, securing the highest-value product objective (27) and abandoning the side objective (15)."
}

DIRECTIVE:
{
  "scope_id": "steady_state-2-value",
  "supersedes": "steady_state-2-priority",
  "version": 2,
  "objective": "Maximize value by completing track and frame objectives. Accept budget breach of 1 unit. Drop errandry and finish objectives.",
  "priorities": [
    "rails",
    "hull",
    "errand",
    "paint"
  ],
  "constraints": [
    "rails unattended <= 1 tick",
    "budget <= 54 (breach accepted)"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "rails"
    },
    {
      "owner": "bo",
      "responsibility": "hull"
    }
  ],
  "success_conditions": [
    "rails completed",
    "hull completed"
  ],
  "review_when": "next_review",
  "decision_summary": "Prioritize high-value track and frame objectives. Accept minor budget breach to complete both. Drop errand and finish objectives due to capacity and dependency constraints."
}

DIRECTIVE: {
  "scope_id": "hull-rails-push",
  "supersedes": "focus-frame-errand",
  "version": 2,
  "objective": "Complete hull to secure frame objective; maintain rails progress to mitigate unattended commitment breach; accept minor budget overage.",
  "priorities": [
    "hull",
    "rails"
  ],
  "constraints": [
    "Total spend <= 54",
    "Rails unattended <= 1 consecutive tick",
    "Paint blocked until hull completes"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "rails"
    },
    {
      "owner": "bo",
      "responsibility": "hull"
    }
  ],
  "success_conditions": [
    "Hull completed",
    "Rails progress maintained continuously",
    "Budget overage minimized"
  ],
  "review_when": "next review",
  "decision_summary": "Reassigned ana from completed errand to rails to prevent commitment breach and pursue track objective; bo continues hull to secure frame objective. Budget overage of 2 accepted to ensure hull completion and rails continuity."
}

DIRECTIVE:
{
  "scope_id": "constraint-4-v2",
  "supersedes": "constraint-4-v1",
  "version": 2,
  "objective": "Complete fit to secure assembly objective; audit is impossible due to constraints.",
  "priorities": [
    "fit"
  ],
  "constraints": [
    "Total spend <= 56",
    "ana cannot work on sensitive tasks"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "fit"
    },
    {
      "owner": "bo",
      "responsibility": "fit"
    }
  ],
  "success_conditions": [
    "fit completed"
  ],
  "review_when": "end",
  "decision_summary": "Reallocation to fit as frame/rig are done. Audit impossible due to sensitive tag on ana. Both actors assigned to fit to finish quickly."
}

DIRECTIVE:
{
  "scope_id": "constraint-5-v2",
  "supersedes": "constraint-5-v1",
  "version": 2,
  "objective": "Complete assembly (frame + fit) and rigging. Abandon audit.",
  "priorities": [
    "frame",
    "fit"
  ],
  "constraints": [
    "Total spend <= 56",
    "Ana cannot work on ledger",
    "fit blocked until frame completes"
  ],
  "responsibilities": [
    {
      "owner": "ana",
      "responsibility": "frame"
    },
    {
      "owner": "bo",
      "responsibility": "frame"
    }
  ],
  "success_conditions": "frame and fit completed within budget.",
  "review_when": "next review",
  "decision_summary": "Ana is forbidden from sensitive ledger work, making audit impossible. Ana moves from completed rig to frame to assist Bo, prioritizing assembly."
}
